const onboardingCopy={en:{language:'Language',start:'Show me jobs',welcome:'A little help to get started'},hi:{language:'भाषा',start:'काम दिखाएँ',welcome:'शुरू करने के लिए थोड़ी मदद'},bn:{language:'ভাষা',start:'কাজ দেখান',welcome:'শুরু করতে একটু সাহায্য'},ta:{language:'மொழி',start:'வேலைகளைக் காட்டு',welcome:'தொடங்குவதற்கு ஒரு சிறிய உதவி'},ml:{language:'ഭാഷ',start:'ജോലികൾ കാണൂ',welcome:'തുടങ്ങാൻ ഒരു ചെറിയ സഹായം'}};
