const payCopy={en:['All pay','Daily wage','Monthly salary'],hi:['सभी वेतन','दैनिक मज़दूरी','मासिक वेतन'],bn:['সব বেতন','দৈনিক মজুরি','মাসিক বেতন'],ta:['அனைத்தும்','தினக்கூலி','மாதச் சம்பளம்'],ml:['എല്ലാ വേതനവും','ദിവസവേതനം','മാസശമ്പളം']};
let payPeriod='';
let activeModal='';
const icons=['▦','⚒','♨','✧','▣','⚙'];
let lang='en',saved=[],category=0,view='all',timer,position=null,geoPending=false,geoMessage='',visibleCount=4,loading=false,feedGeneration=0;
try{lang=localStorage.getItem('kams-language')||'en';saved=JSON.parse(localStorage.getItem('kams-saved')||'[]');if(!Array.isArray(saved))saved=[]}catch{}
if(!copy[lang])lang='en';
const $=s=>document.querySelector(s),t=k=>copy[lang][k];
const title=j=>t('titles')[j.kind];
function persist(){try{localStorage.setItem('kams-language',lang);localStorage.setItem('kams-saved',JSON.stringify(saved))}catch{}}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',5000)}
function render(){
 document.documentElement.lang=lang;
 document.querySelectorAll('[data-t]').forEach(e=>e.innerHTML=t(e.dataset.t));
 $('#languageSelect').value=lang;$('#languageSelect').setAttribute('aria-label',t('language'));document.querySelector('.header-language').title=t('language');
 $('#search').placeholder=t('placeholder');$('#search').setAttribute('aria-label',t('placeholder'));$('#district').setAttribute('aria-label',t('location'));
 const district=$('#district').value;
 $('#district').innerHTML=`<option value="">${t('allDistricts')}</option>`+places[lang].map((p,i)=>`<option value="${i}">${p}</option>`).join('');$('#district').value=district;
 $('#categories').innerHTML=t('categories').map((c,i)=>`<button class="category ${category===i?'active':''}" data-cat="${i}" aria-pressed="${category===i}"><span class="cat-icon" aria-hidden="true">${icons[i]}</span>${c}</button>`).join('');
 $('#payPeriods').setAttribute('aria-label',t('payLabel'));$('#payPeriods').innerHTML=['','day','month'].map((unit,i)=>`<button data-pay="${unit}" class="${payPeriod===unit?'active':''}" aria-pressed="${payPeriod===unit}">${payCopy[lang][i]}</button>`).join('');
 updateLocationStatus();renderJobs();
}
function distance(j){if(!position)return Infinity;const [lat,lng]=coordinates[j.place],r=Math.PI/180;const a=Math.sin((lat-position.lat)*r/2)**2+Math.cos(position.lat*r)*Math.cos(lat*r)*Math.sin((lng-position.lng)*r/2)**2;return 6371*2*Math.atan2(Math.sqrt(a),Math.sqrt(Math.max(0,1-a)))}
function filtered(){const q=$('#search').value.trim().toLocaleLowerCase(),d=$('#district').value;const results=data.filter(j=>(!payPeriod||j.unit===payPeriod)&&(!category||j.cat===category)&&(d===''||j.place===Number(d))&&(view!=='saved'||saved.includes(j.id))&&(!q||[title(j),places[lang][j.place],copy.en.titles[j.kind],places.en[j.place],t('categories')[j.cat]].join(' ').toLocaleLowerCase().includes(q)));return position?results.sort((a,b)=>distance(a)-distance(b)||a.id-b.id):results}
function card(j){return `<article class="job" data-job-id="${j.id}"><div class="job-top"><span class="job-icon" aria-hidden="true">${icons[j.cat]}</span><button class="save ${saved.includes(j.id)?'is-saved':''}" data-save="${j.id}" aria-label="${saved.includes(j.id)?t('unsave'):t('save')}" aria-pressed="${saved.includes(j.id)}">${saved.includes(j.id)?'♥':'♡'}</button></div><h3><button class="job-title" data-details="${j.id}">${title(j)}</button></h3><div class="company">${t('categories')[j.cat]}</div><div class="job-place">◎ &nbsp;${places[lang][j.place]}${position?`<span class="distance">≈ ${Math.round(distance(j))} ${t('km')}</span>`:''}</div><div class="pay">₹${j.pay} <small>/ ${t(j.unit)}</small></div><div class="tags">${j.benefits.map(b=>`<span class="tag">${t(b)}</span>`).join('')}</div><div class="job-bottom"><button class="contact" data-contact="${j.id}">${t('contact')}</button><button class="audio" data-audio="${j.id}" aria-label="${t('listen')}: ${title(j)}">◖))</button></div><div class="card-foot"><button data-details="${j.id}">${t('details')}</button><span>${t('registrationRequired')}</span></div></article>`}
function pageSize(){return window.matchMedia('(max-width:780px)').matches?3:window.matchMedia('(max-width:1050px)').matches?4:6}
function updateFeed(){const total=filtered().length;$('#loadMore').hidden=visibleCount>=total;$('#loadMore').disabled=loading;$('#feedStatus').textContent=loading?t('loading'):visibleCount>=total&&total?t('end'):'';$('#feedSentinel').hidden=visibleCount>=total;$('#jobs').setAttribute('aria-busy',String(loading))}
function renderJobs(reset=true){if(reset){feedGeneration++;visibleCount=pageSize();loading=false}const jobs=filtered();$('#resultTitle').textContent=view==='saved'?t('saved'):position?t('nearby'):t('results');$('#count').textContent=`${jobs.length} ${t('count')}`;document.querySelectorAll('[data-view]').forEach(e=>{e.classList.toggle('active',e.dataset.view===view);e.setAttribute('aria-current',e.dataset.view===view?'page':'false')});$('#jobs').innerHTML=jobs.length?jobs.slice(0,visibleCount).map(card).join(''):`<div class="empty"><h3>${t('empty')}</h3><button id="reset">${t('reset')}</button></div>`;updateFeed()}
function loadNext(){const jobs=filtered();if(loading||visibleCount>=jobs.length)return;loading=true;const generation=feedGeneration;updateFeed();requestAnimationFrame(()=>{if(generation!==feedGeneration)return;const next=jobs.slice(visibleCount,visibleCount+pageSize());$('#jobs').insertAdjacentHTML('beforeend',next.map(card).join(''));visibleCount+=next.length;loading=false;updateFeed()})}
function speak(text){if(!('speechSynthesis' in window)){toast(t('voiceMissing'));return}speechSynthesis.cancel();const voice=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith(lang));if(!voice){toast(t('voiceMissing'));return}const u=new SpeechSynthesisUtterance(text);u.voice=voice;u.lang=voice.lang;u.rate=.85;u.onerror=e=>{if(e.error!=='interrupted'&&e.error!=='canceled')toast(t('voiceError'))};speechSynthesis.speak(u)}
function jobSpeech(j){return `${title(j)}. ${places[lang][j.place]}. ${t('payLabel')}: ${j.pay} ${lang==='en'?'rupees':'₹'} ${t(j.unit)}. ${t('schedule')}. ${j.benefits.map(t).join('. ')}. ${t('demo')}`}
function openModal(html,type=''){activeModal=type;$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function showDetails(id){const j=data.find(j=>j.id===id);if(!j)return;openModal(`<span class="job-icon" aria-hidden="true">${icons[j.cat]}</span><h2 id="modalTitle">${title(j)}</h2><p>${places[lang][j.place]}</p><dl><dt>${t('payLabel')}</dt><dd>₹${j.pay} / ${t(j.unit)}</dd><dt>${t('hours')}</dt><dd>${t('schedule')}</dd><dt>${t('benefits')}</dt><dd>${j.benefits.map(t).join(' · ')}</dd></dl><button class="listen" data-audio="${id}">◖)) ${t('listen')}</button><button class="primary full" data-contact="${id}">${t('contact')}</button><p class="demo-note">${t('contactSample')}</p>`)}
function showRegister(id){const j=data.find(j=>j.id===id);openModal(`<span class="modal-eyebrow">${t('previewOnly')}</span><h2 id="modalTitle">${t('register')}</h2><p class="modal-sub">${t('registerSub')}</p>${j?`<div class="selected-job"><strong>${title(j)}</strong><span>${places[lang][j.place]} · ₹${j.pay} / ${t(j.unit)}</span></div>`:''}<div class="auth-notice">${t('authUnavailable')}</div><form id="registrationForm" autocomplete="on"><label for="workerName">${t('name')}</label><input id="workerName" name="name" autocomplete="name" maxlength="80" required placeholder="${t('name')}"><label for="workerPhone">${t('phone')}</label><div class="phone-input"><span>+91</span><input id="workerPhone" name="phone" type="tel" inputmode="numeric" autocomplete="tel-national" pattern="[6-9][0-9]{9}" maxlength="10" title="${t('safePhone')}" required placeholder="9876543210"></div><small>${t('otpHint')}</small><button class="primary full" type="submit">${t('sendOtp')}</button></form><div class="or"><span>${t('or')}</span></div><button id="googleSignIn" class="google full"><span aria-hidden="true">G</span> ${t('google')}</button><p id="authStatus" class="auth-status" role="status"></p><button id="previewLocation" class="preview-step">${t('previewLocation')}</button>`);$('#registrationForm').addEventListener('submit',e=>{e.preventDefault();const name=$('#workerName');name.setCustomValidity(name.value.trim()? '':t('safeName'));if(!e.target.reportValidity())return;$('#authStatus').textContent=t('providerNeeded')});$('#workerName').addEventListener('input',e=>e.target.setCustomValidity(''))}
function showLocation(preview=false){openModal(`${preview?`<span class="modal-eyebrow">${t('previewOnly')}</span>`:''}<span class="location-symbol" aria-hidden="true">◎</span><h2 id="modalTitle">${t('locationTitle')}</h2><p class="modal-sub">${t('locationBody')}</p><button id="allowLocation" class="primary full">${t('allowLocation')}</button><button id="chooseDistrict" class="outline full">${t('chooseDistrict')}</button><p class="privacy-note">${t('locationPrivate')}</p><button id="notNow" class="subtle full">${t('notNow')}</button>`)}
function showDistrict(){openModal(`<h2 id="modalTitle">${t('chooseDistrict')}</h2><p class="modal-sub">${t('chooseDistrictHint')}</p><label for="manualDistrict">${t('districtLabel')}</label><select id="manualDistrict" class="district-select">${places[lang].map((p,i)=>`<option value="${i}">${p}</option>`).join('')}</select><button id="applyDistrict" class="primary full">${t('applyDistrict')}</button>`);$('#manualDistrict').value=$('#district').value||'0'}
function updateLocationStatus(){$('#locationStatus').textContent=geoPending?t('locating'):geoMessage?t(geoMessage):position?t('approx'):'';$('#nearMe').disabled=geoPending;$('#nearMe').classList.toggle('enabled',!!position);$('#clearLocation').hidden=!position;$('#locationFeedback').hidden=!geoPending&&!geoMessage&&!position;}
function requestLocation(){if(geoPending)return;$('#modal').close();geoMessage='';if(!navigator.geolocation){geoMessage='locationUnsupported';updateLocationStatus();showDistrict();return}geoPending=true;updateLocationStatus();navigator.geolocation.getCurrentPosition(result=>{geoPending=false;position={lat:result.coords.latitude,lng:result.coords.longitude};$('#district').value='';geoMessage='';updateLocationStatus();renderJobs()},error=>{geoPending=false;geoMessage=error.code===1?'locationDenied':'locationError';updateLocationStatus();toast(t(geoMessage));showDistrict()},{enableHighAccuracy:false,timeout:10000,maximumAge:60000})}
function showHelp(){openModal(`<div class="welcome-mark" aria-hidden="true">k</div><span class="modal-eyebrow">kerala-kams</span><h2 id="modalTitle">${t('welcome')}</h2><label for="welcomeLanguage">${t('language')}</label><select id="welcomeLanguage" class="welcome-language" aria-label="${t('language')}">${Object.entries({bn:'বাংলা',hi:'हिन्दी',ta:'தமிழ்',ml:'മലയാളം',en:'English'}).map(([code,name])=>`<option lang="${code}" value="${code}">${name}</option>`).join('')}</select><ol class="welcome-steps">${t('steps').map(s=>`<li>${s}</li>`).join('')}</ol><div class="welcome-safety">${t('safeBody')}</div><button class="listen" id="hearHelp">◖)) ${t('listen')}</button><button id="finishWelcome" class="primary full">${t('start')}</button>`, 'welcome');$('#welcomeLanguage').value=lang;$('#welcomeLanguage').addEventListener('change',e=>{changeLanguage(e.target.value);showHelp();$('#welcomeLanguage').focus()})}
function changeLanguage(code){if(!copy[code])return;lang=code;window.speechSynthesis?.cancel();persist();render()}
function rememberWelcome(){try{localStorage.setItem('kams-welcome-seen','1')}catch{}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.pay!==undefined){payPeriod=b.dataset.pay;render()}
 if(b.dataset.cat!==undefined){category=Number(b.dataset.cat);render()}
 if(b.dataset.view){view=b.dataset.view;renderJobs();window.scrollTo({top:0,behavior:'smooth'})}
 if(b.dataset.save!==undefined){const id=Number(b.dataset.save);saved=saved.includes(id)?saved.filter(n=>n!==id):[...saved,id];persist();if(view==='saved'){renderJobs(false)}else{b.classList.toggle('is-saved',saved.includes(id));b.setAttribute('aria-pressed',String(saved.includes(id)));b.setAttribute('aria-label',t(saved.includes(id)?'unsave':'save'));b.textContent=saved.includes(id)?'♥':'♡'}toast(t(saved.includes(id)?'savedToast':'removedToast'))}
 if(b.dataset.details!==undefined)showDetails(Number(b.dataset.details));
 if(b.dataset.contact!==undefined)showRegister(Number(b.dataset.contact));
 if(b.dataset.audio!==undefined)speak(jobSpeech(data.find(j=>j.id===Number(b.dataset.audio))));
 if(b.id==='reset'){payPeriod='';category=0;view='all';$('#search').value='';$('#district').value='';render()}
 if(b.id==='hearHelp')speak(t('steps').join('. '));
 if(b.id==='finishWelcome')$('#modal').close();
 if(b.id==='account')showRegister();
 if(b.id==='googleSignIn')$('#authStatus').textContent=t('providerNeeded');
 if(b.id==='previewLocation')showLocation(true);
 if(b.id==='allowLocation')requestLocation();
 if(b.id==='chooseDistrict')showDistrict();
 if(b.id==='notNow')$('#modal').close();
 if(b.id==='applyDistrict'){position=null;geoMessage='';$('#district').value=$('#manualDistrict').value;$('#modal').close();updateLocationStatus();renderJobs()}
});
$('#search').addEventListener('input',()=>renderJobs());$('#district').addEventListener('change',()=>renderJobs());
$('#searchBtn').onclick=()=>{renderJobs();$('#resultTitle').scrollIntoView({behavior:'smooth',block:'center'})};
$('#languageSelect').addEventListener('change',e=>changeLanguage(e.target.value));$('#closeModal').onclick=()=>$('#modal').close();
$('#modal').addEventListener('close',()=>{if(!$('#modal').open){if(activeModal==='welcome')rememberWelcome();activeModal='';$('#modalBody').replaceChildren()}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
$('#listenPage').onclick=()=>speak(t('steps').join('. '));
$('#nearMe').onclick=()=>showLocation();$('#clearLocation').onclick=()=>{position=null;geoMessage='';updateLocationStatus();renderJobs()};$('#loadMore').onclick=loadNext;
if('speechSynthesis' in window)speechSynthesis.getVoices();render();
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting))loadNext()},{rootMargin:'250px 0px'});observer.observe($('#feedSentinel'))}

let showWelcome=true;try{showWelcome=localStorage.getItem('kams-welcome-seen')!=='1'}catch{}
if(showWelcome)showHelp();
